package com.example.rokidgeminisecretary;
import org.json.*;
public class CheckpointPhoneTest{static int count;static void ok(boolean v){count++;if(!v)throw new AssertionError("checkpoint "+count);}public static void main(String[] args)throws Exception{long now=1000000;JSONObject recognition=new JSONObject().put("source","VOICE").put("text","認識文").put("phase","RECOGNIZED").put("at",now-1000);JSONObject selected=CorrectionDraft.select(recognition,new JSONArray(),now);ok(selected.getBoolean("available"));ok(selected.getString("text").equals("認識文"));recognition.put("source","TOPIC");ok(!CorrectionDraft.select(recognition,new JSONArray(),now).getBoolean("available"));recognition.put("source","VOICE").put("phase","PARTIAL");ok(!CorrectionDraft.select(recognition,new JSONArray(),now).getBoolean("available"));recognition.put("phase","RECOGNIZED").put("at",now+1);ok(!CorrectionDraft.select(recognition,new JSONArray(),now).getBoolean("available"));recognition.put("at",now-900001);ok(!CorrectionDraft.select(recognition,new JSONArray(),now).getBoolean("available"));JSONObject row=new JSONObject().put("key","a".repeat(64)).put("tracked",true).put("time",now-10).put("message","送信本文");ok(CorrectionDraft.select(recognition,new JSONArray().put(row),now).getString("text").equals("送信本文"));row.put("key","invalid");ok(!CorrectionDraft.select(null,new JSONArray().put(row),now).getBoolean("available"));row.put("key","a".repeat(64)).put("message","a".repeat(2401));ok(!CorrectionDraft.select(null,new JSONArray().put(row),now).getBoolean("available"));JSONObject state=new JSONObject().put("connected",false).put("receivedAt",now-16000).put("conversation",new JSONObject().put("phase","RUNNING").put("reason","CONNECTION"));String label=ConnectionCheckpoint.describe(state,now);ok(label.contains("現在は未確認"));ok(label.contains("Geminiへの接続"));ok(label.contains("16秒前"));ok(label.contains("自動再送しません"));ok(ConnectionCheckpoint.describe(new JSONObject(),now).contains("結果情報なし"));System.out.println("PASS checkpoint phone "+count);}}
